package e.e.a;
/** Neutral controls stay close to the dialog surface in both themes. */
public final class DialogColors {private DialogColors(){}public static final int LIST_CORNER=0x99999999;public static final int SURFACE_DARK=0xff191b20;public static final int INK_DARK=0xffeeeeee,INK_LIGHT=0xff202124,MUTED_DARK=0xffb7bac3,MUTED_LIGHT=0xff666a73,ACCENT_DARK=0xff52cca3;public static int ink(boolean dark){return dark?INK_DARK:INK_LIGHT;}public static int muted(boolean dark){return dark?MUTED_DARK:MUTED_LIGHT;}public static int accent(int value,boolean dark){int r=(value>>16)&255,g=(value>>8)&255,b=value&255;return dark&&(g<=r||b>g*1.05)?ACCENT_DARK:value;}public static boolean purple(int color){int r=(color>>16)&255,g=(color>>8)&255,b=color&255;int max=Math.max(r,Math.max(g,b)),min=Math.min(r,Math.min(g,b));float delta=max-min;if(delta<12)return false;float hue=max==r?60*((g-b)/delta):max==g?60*(2+(b-r)/delta):60*(4+(r-g)/delta);if(hue<0)hue+=360;return hue>=245&&hue<=355;}public static int secondary(int surface,boolean dark){float amount=dark?.012f:.04f;int target=dark?255:0;int r=Math.round(((surface>>16)&255)*(1-amount)+target*amount),g=Math.round(((surface>>8)&255)*(1-amount)+target*amount),b=Math.round((surface&255)*(1-amount)+target*amount);return 0xff000000|(r<<16)|(g<<8)|b;}public static int onAccent(int color){double l=0;double[] w={.0722,.7152,.2126};for(int n=0;n<3;n++){double v=((color>>(n*8))&255)/255.0;l+=w[n]*(v<=.04045?v/12.92:Math.pow((v+.055)/1.055,2.4));}return 1.05/(l+.05)>=4.5?0xffffffff:(l+.05)/(.0056+.05)>=4.5?0xff101114:0xff000000;}}
